#[no_mangle]
pub extern "C" fn hinted_quotient_i32(a: i32, b: i32) -> i32 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
        core::hint::assert_unchecked(!(a == i32::MIN && b == -1));
    }
    a / b
}

#[no_mangle]
pub extern "C" fn hinted_remainder_i32(a: i32, b: i32) -> i32 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
        core::hint::assert_unchecked(!(a == i32::MIN && b == -1));
    }
    a % b
}

